<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Archive, Edit3, Plus, RotateCcw, Save, Trash2, Truck, X } from 'lucide-vue-next'
import SectionPanel from '../components/SectionPanel.vue'
import StatusBadge from '../components/StatusBadge.vue'
import WorkspaceStickyStack from '../components/WorkspaceStickyStack.vue'
import { suppliersApi, type SupplierPayload, type SupplierRecord } from '../api/suppliers'
import { formatDateTime } from '../utils/date'
import { confirmAction, normalizeError } from '../ui/feedback'
import SearchFilterBar from '../components/SearchFilterBar.vue'
import SearchField from '../components/SearchField.vue'
import SelectField from '../components/SelectField.vue'
const emit=defineEmits<{notify:[string]}>();type Filter='Active'|'Archived'|'All';const rows=ref<SupplierRecord[]>([]);const selected=ref<string|null>(null);const filter=ref<Filter>('Active');const search=ref('');const editing=ref(false);const form=ref<SupplierPayload>(empty());const error=ref('');const loading=ref(false)
const current=computed(()=>rows.value.find(v=>v.id===selected.value)??null);const filtered=computed(()=>rows.value.filter(v=>(filter.value==='All'||(filter.value==='Active'?v.active:!v.active))&&(!search.value||[v.name,v.code,v.phone,v.email].join(' ').toLowerCase().includes(search.value.toLowerCase()))));
onMounted(load);function empty():SupplierPayload{return{name:'',code:'',phone:'',email:'',address:'',notes:''}};async function load(){loading.value=true;try{rows.value=await suppliersApi.list(true);if(!selected.value&&rows.value[0])selected.value=rows.value[0].id}catch(e){error.value=normalizeError(e).message}finally{loading.value=false}};function startCreate(){selected.value=null;form.value=empty();editing.value=true};function startEdit(){if(!current.value)return;form.value={name:current.value.name,code:current.value.code,phone:current.value.phone,email:current.value.email,address:current.value.address,notes:current.value.notes};editing.value=true};async function save(){try{const v=editing.value&&selected.value?await suppliersApi.update(selected.value,form.value):await suppliersApi.create(form.value) as unknown as SupplierRecord;rows.value=rows.value.some(x=>x.id===v.id)?rows.value.map(x=>x.id===v.id?v:x):[v,...rows.value];selected.value=v.id;editing.value=false;emit('notify','Supplier saved.')}catch(e){error.value=normalizeError(e).message}};async function setActive(active:boolean){if(!current.value)return;try{const v=active?await suppliersApi.reactivate(current.value.id):await suppliersApi.archive(current.value.id);rows.value=rows.value.map(x=>x.id===v.id?v:x);emit('notify',active?'Supplier reactivated.':'Supplier archived.')}catch(e){error.value=normalizeError(e).message}};async function remove(){if(!current.value||!(await confirmAction({title:'Delete supplier',message:'Delete this supplier permanently?',confirmLabel:'Delete supplier',danger:true})))return;try{await suppliersApi.remove(current.value.id);rows.value=rows.value.filter(x=>x.id!==current.value!.id);selected.value=null;emit('notify','Supplier deleted.')}catch(e){error.value=normalizeError(e).message}}
</script>
<template><div><WorkspaceStickyStack><header><div><p>Catalog / purchasing</p><h1>Suppliers</h1><p>Keep supplier contacts and purchasing history safe and readable.</p></div><button class="btn btn-primary" type="button" @click="startCreate"><Plus :size="16"/> New supplier</button></header><SearchFilterBar><template #search><SearchField v-model="search" label="Search suppliers" placeholder="Search suppliers"/></template><template #filters><SelectField v-model="filter" label="Status" :options="['Active', 'Archived', 'All'].map((value) => ({ label: value, value }))"/></template><template #count><span>{{ filtered.length }} shown</span></template></SearchFilterBar></WorkspaceStickyStack><div v-if="error" role="alert">{{ error }} <button class="btn btn-ghost" @click="error=''" aria-label="Dismiss"><X :size="14"/></button></div><section><SectionPanel title="Supplier register" subtitle="Select a supplier to inspect or edit."><div v-if="loading">Loading suppliers…</div><div v-else-if="filtered.length"><table class="table table-zebra w-full"><thead><tr><th>Supplier</th><th>Contact</th><th>Status</th><th>Updated</th></tr></thead><tbody><tr v-for="v in filtered" :key="v.id" :class="{'bg-base-300':selected===v.id}" @click="selected=v.id"><td><span>{{v.name}}</span><span>{{v.code||'No code'}}</span></td><td>{{v.phone||v.email||'—'}}</td><td><StatusBadge :label="v.active?'Active':'Archived'" :tone="v.active?'green':'slate'"/></td><td>{{formatDateTime(v.updatedAt)}}</td></tr></tbody></table></div><div v-else><Truck :size="22"/><p>No suppliers found.</p></div></SectionPanel><SectionPanel v-if="editing" title="Supplier editor" subtitle="Persisted in the local database."><form @submit.prevent="save"><label class="form-control gap-1"><span>Name</span><input class="input input-bordered w-full min-w-0" v-model="form.name" required /></label><div><label class="form-control gap-1"><span>Code</span><input class="input input-bordered w-full min-w-0" v-model="form.code" /></label><label class="form-control gap-1"><span>Phone</span><input class="input input-bordered w-full min-w-0" v-model="form.phone" /></label></div><label class="form-control gap-1"><span>Email</span><input class="input input-bordered w-full min-w-0" v-model="form.email" type="email" /></label><label class="form-control gap-1"><span>Address</span><textarea class="textarea textarea-bordered w-full min-w-0" v-model="form.address" rows="2"/></label><label class="form-control gap-1"><span>Notes</span><textarea class="textarea textarea-bordered w-full min-w-0" v-model="form.notes" rows="3"/></label><div><button class="btn btn-ghost" type="button" @click="editing=false">Cancel</button><button class="btn btn-ghost"><Save :size="15"/> Save</button></div></form></SectionPanel><SectionPanel v-else-if="current" title="Supplier inspector" subtitle="Archive and delete have different meanings."><div><div><Truck :size="19"/></div><div><h3>{{current.name}}</h3><p>{{current.code||'No code'}}</p></div></div><div><StatusBadge :label="current.active?'Active':'Archived'" :tone="current.active?'green':'slate'"/></div><dl><div><dt>Phone</dt><dd>{{current.phone||'—'}}</dd></div><div><dt>Email</dt><dd>{{current.email||'—'}}</dd></div><div><dt>Address</dt><dd>{{current.address||'—'}}</dd></div><div><dt>Updated</dt><dd>{{formatDateTime(current.updatedAt)}}</dd></div></dl><div><button class="btn btn-ghost" @click="startEdit"><Edit3 :size="15"/> Edit</button><button class="btn btn-ghost" @click="setActive(!current.active)"><RotateCcw v-if="!current.active" :size="15"/><Archive v-else :size="15"/> {{current.active?'Archive':'Reactivate'}}</button><button class="btn btn-ghost" @click="remove"><Trash2 :size="15"/> Delete</button></div></SectionPanel><SectionPanel v-else title="Supplier inspector" subtitle="Select a row to inspect it."><div><Truck :size="20"/><p>Supplier details will appear here.</p></div></SectionPanel></section></div></template>
